PH=ref('Current Phenytoin Prescribing Information','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=db8c69b0-4697-433e-98c7-b0b2d2c52a83')
CB=ref('Current Carbamazepine Prescribing Information','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8d409411-aa9f-4f3a-a52c-fbcb0c3ec053')
